1	import Anthropic from "@anthropic-ai/sdk";
2	import { MODELS, EFFORT } from "./models";
3	
4	export type AgentEvent =
5	  | { type: "status"; text: string }
6	  | { type: "text"; text: string }
7	  | { type: "file"; path: string; action: "write" | "delete" }
8	  | {
9	      type: "usage";
10	      model: string;
11	      inputTokens: number;
12	      outputTokens: number;
13	      cacheReadTokens: number;
14	      cacheWriteTokens: number;
15	    };
16	
17	export type FileMap = Record<string, string>;
18	
19	const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
20	
21	// Generated sites are real Vite + React + TypeScript + Tailwind apps, built
22	// server-side (lib/build-site.ts) into static output served from a
23	// locked-down CSP that blocks every external host — "no CDN, no remote
24	// anything" is a hard constraint rather than a style preference.
25	const SYSTEM = `You are Kodely's site builder. You turn a plain-English description into a real, working website — a genuine Vite + React + TypeScript + Tailwind app, not a static HTML mockup.
26	
27	## The project you're editing
28	Every project starts from a real foundation (package.json, vite.config.ts, tsconfig.json, index.html, src/main.tsx, src/index.css, src/App.tsx, and a few UI primitives under src/components/ui/). You almost never touch the config files — package.json, vite.config.ts, tsconfig.json and src/main.tsx are already correct and there is no way to add a new dependency, so leave them alone unless something is actually broken. Your work happens in \`src/App.tsx\`, new files under \`src/components/\`, and \`src/index.css\`.
29	
30	### index.html — the one config file you MUST edit
31	Every new site needs a real \`<head>\`. The foundation ships a placeholder title and a site is never actually called "Kodely Site" — that title is what shows in the browser tab, in Google, and in every link preview when someone shares the URL. Write, in the site's own language:
32	
33	- \`<title>\` — the real business or site name, with a short qualifier where it helps (e.g. "Bloom Pilates — Reformer studio in Denver"). Under ~60 characters.
34	- \`<meta name="description">\` — one specific sentence about what THIS business offers, ~150 characters. Describe the business, not the template.
35	- \`<meta property="og:title">\` and \`<meta property="og:description">\` — usually the same values; these are what appear when the link is shared.
36	- \`<html lang="...">\` — the correct language if the content is not English.
37	
38	Leave the rest of index.html alone (charset, viewport, the root div, the module script). Never add \`<link>\` or \`<script>\` tags pointing at a remote host — published sites run under a strict CSP that blocks external requests, so they fail silently.
39	
40	## Output contract
41	Use the write_file and delete_file tools. Always pass the complete final file — there is no patch tool.
42	- Build real, composable React components — a Hero, a FeatureGrid, a Footer — not one giant App.tsx.
43	- Style with Tailwind utility classes. The existing primitives (Button, Card, Section, Nav in src/components/ui/) are a starting point — reuse them, extend them, or write new ones as the design calls for, but keep the same quality bar.
44	- Multi-page: this is a single-page app. Build distinct sections/routes as components conditionally rendered or scrolled to, not separate .html files.
45	
46	## Hard constraints — these break the sandboxed build/serve, not just style
47	- NO external requests. No CDN scripts, no Google Fonts, no remote images, no
48	  fetch/XHR to other origins — the CSP blocks all of them at serve time.
49	- Only the dependencies already in package.json exist (react, react-dom). You
50	  cannot add packages — there is no install step per generation.
51	- Images are inline SVG, CSS gradients, or data: URIs. Never <img src="https://...">.
52	- Fonts come from the system stack (ui-sans-serif, -apple-system, "Segoe UI", Inter, sans-serif) — no @import or <link> for web fonts.
53	
54	## Quality bar
55	Ship something that looks designed, not templated. Real, specific copy for the
56	subject at hand — never "Lorem ipsum" and never placeholder headings like
57	"Your Title Here". Responsive down to 380px. Semantic HTML, labelled form
58	controls, sufficient colour contrast, and a visible :focus style. Include a
59	dark-mode treatment unless the brief implies otherwise. Give the page one
60	distinctive visual idea rather than a generic hero-plus-three-cards.
61	
62	## Editing an existing site
63	You are given the current source files. Change only what the request calls
64	for — do not restyle or restructure components the user did not ask about.
65	
66	## Working style
67	Write the files first, then finish with two or three sentences telling the user
68	what you built and what they might want to change next. Do not narrate each file
69	as you write it, and do not paste code into your reply — the user sees a live
70	preview of the result.`;
71	
72	const TOOLS: Anthropic.Tool[] = [
73	  {
74	    name: "write_file",
75	    description:
76	      "Create a file or replace its entire contents. Always pass the complete final file, never a fragment or a diff.",
77	    input_schema: {
78	      type: "object",
79	      properties: {
80	        path: {
81	          type: "string",
82	          description: "Project-relative path, e.g. 'index.html' or 'styles.css'. No leading slash.",
83	        },
84	        content: { type: "string", description: "The complete contents of the file." },
85	      },
86	      required: ["path", "content"],
87	    },
88	  },
89	  {
90	    name: "delete_file",
91	    description: "Delete a file that is no longer part of the site.",
92	    input_schema: {
93	      type: "object",
94	      properties: { path: { type: "string", description: "Project-relative path to delete." } },
95	      required: ["path"],
96	    },
97	  },
98	];
99	
100	/** Reject path traversal and absolute paths before anything touches the DB. */
101	export function normalizePath(raw: string): string | null {
102	  const path = raw.trim().replace(/^\.?\//, "");
103	  if (!path || path.length > 200) return null;
104	  if (path.includes("..") || path.startsWith("/") || path.includes("\\")) return null;
105	  if (!/^[A-Za-z0-9._/-]+$/.test(path)) return null;
106	  return path;
107	}
108	
109	function describeFiles(files: FileMap): string {
110	  const paths = Object.keys(files);
111	  if (paths.length === 0) return "The project is empty — this is the first build.";
112	  return [
113	    "Current files in the project:",
114	    ...paths.map((p) => `\n--- ${p} ---\n${files[p]}`),
115	  ].join("\n");
116	}
117	
118	type RunOptions = {
119	  /** Prior turns, oldest first. */
120	  history: { role: "user" | "assistant"; content: string }[];
121	  request: string;
122	  files: FileMap;
123	  /** First build of a site vs a follow-up tweak — drives how hard we think. */
124	  kind: "create" | "edit";
125	  /** A reference image attached to this turn's request (vision input). */
126	  image?: { mediaType: string; data: string };
127	  /** Applies the write; returning false rejects it (e.g. bad path). */
128	  onWrite: (path: string, content: string) => Promise<boolean>;
129	  onDelete: (path: string) => Promise<boolean>;
130	  /**
131	   * Aborted when the client disconnects (tab closed, network drop). Actually
132	   * cancels the in-flight Anthropic request instead of letting it run to
133	   * completion for nobody — a disconnect shouldn't mean paying full price for
134	   * a generation no one will ever see the result of.
135	   */
136	  signal?: AbortSignal;
137	};
138	
139	/**
140	 * Runs the plan → generate → apply loop, streaming progress as it goes.
141	 * Token usage is accumulated across every turn so the caller can meter the
142	 * true cost of the build (including the repair turns, which we may not bill).
143	 */
144	// Which generation engine to use.
145	//   api (default) — metered Anthropic API via ANTHROPIC_API_KEY. Real cost,
146	//                   real usage telemetry, real credit charges.
147	//   sdk           — Claude Agent SDK on this machine's `claude setup-token`
148	//                   subscription login. No metered spend, so no cost data and
149	//                   0 credits charged. See lib/agent-sdk.ts for the caveats.
150	// Defaults to `api` so a fresh clone never silently runs on someone's personal
151	// subscription; the environment opts in.
152	export const ENGINE = process.env.KODELY_ENGINE === "sdk" ? "sdk" : "api";
153	
154	export async function* runAgent(opts: RunOptions): AsyncGenerator<AgentEvent> {
155	  if (ENGINE === "sdk") {
156	    // Deliberately no try/catch fallback to the API engine: if the SDK is not
157	    // authenticated this must fail loudly rather than quietly spend money on
158	    // the metered key the operator asked not to use.
159	    const { runAgentSdk } = await import("./agent-sdk");
160	    yield* runAgentSdk(opts, SYSTEM);
161	    return;
162	  }
163	
164	  const model = MODELS.builder;
165	  // Effort is the sharpest cost lever we have: a first build is a blank-page
166	  // design problem and earns `high`, while a targeted tweak lands the same
167	  // result at `medium` for a fraction of the thinking tokens.
168	  const effort = opts.kind === "create" ? EFFORT.create : EFFORT.edit;
169	
170	  const messages: Anthropic.MessageParam[] = [];
171	  for (const turn of opts.history) {
172	    messages.push({ role: turn.role, content: turn.content });
173	  }
174	  const requestText = `${describeFiles(opts.files)}\n\n--- Request ---\n${opts.request}`;
175	  if (opts.image) {
176	    messages.push({
177	      role: "user",
178	      content: [
179	        {
180	          type: "image",
181	          source: {
182	            type: "base64",
183	            media_type: opts.image.mediaType as "image/png" | "image/jpeg" | "image/webp",
184	            data: opts.image.data,
185	          },
186	        },
187	        { type: "text", text: `${requestText}\n\n(A reference image is attached above — use it as visual/style guidance for the site.)` },
188	      ],
189	    });
190	  } else {
191	    messages.push({ role: "user", content: requestText });
192	  }
193	
194	  const totals = {
195	    inputTokens: 0,
196	    outputTokens: 0,
197	    cacheReadTokens: 0,
198	    cacheWriteTokens: 0,
199	  };
200	
201	  // Bounded so a confused model can never bill the user for an endless loop.
202	  const MAX_TURNS = 8;
203	
204	  for (let turn = 0; turn < MAX_TURNS; turn++) {
205	    if (opts.signal?.aborted) return;
206	
207	    const stream = anthropic.messages.stream(
208	      {
209	        model,
210	        max_tokens: 32_000,
211	        thinking: { type: "adaptive" },
212	        output_config: { effort },
213	        system: [{ type: "text", text: SYSTEM, cache_control: { type: "ephemeral" } }],
214	        tools: TOOLS,
215	        messages,
216	      },
217	      { signal: opts.signal },
218	    );
219	
220	    for await (const event of stream) {
221	      if (event.type === "content_block_delta" && event.delta.type === "text_delta") {
222	        yield { type: "text", text: event.delta.text };
223	      }
224	    }
225	
226	    const message = await stream.finalMessage();
227	    totals.inputTokens += message.usage.input_tokens ?? 0;
228	    totals.outputTokens += message.usage.output_tokens ?? 0;
229	    totals.cacheReadTokens += message.usage.cache_read_input_tokens ?? 0;
230	    totals.cacheWriteTokens += message.usage.cache_creation_input_tokens ?? 0;
231	
232	    if (message.stop_reason === "refusal") {
233	      throw new Error(
234	        "The request was declined. Try describing the site you want in different terms.",
235	      );
236	    }
237	
238	    const toolUses = message.content.filter(
239	      (b): b is Anthropic.ToolUseBlock => b.type === "tool_use",
240	    );
241	
242	    if (toolUses.length === 0) {
243	      yield { type: "usage", model, ...totals };
244	      return;
245	    }
246	
247	    messages.push({ role: "assistant", content: message.content });
248	
249	    const results: Anthropic.ToolResultBlockParam[] = [];
250	    for (const use of toolUses) {
251	      const input = use.input as { path?: string; content?: string };
252	      const path = normalizePath(input.path ?? "");
253	
254	      if (!path) {
255	        results.push({
256	          type: "tool_result",
257	          tool_use_id: use.id,
258	          content: `Rejected: '${input.path}' is not a valid project-relative path.`,
259	          is_error: true,
260	        });
261	        continue;
262	      }
263	
264	      if (use.name === "write_file") {
265	        const ok = await opts.onWrite(path, input.content ?? "");
266	        if (ok) yield { type: "file", path, action: "write" };
267	        results.push({
268	          type: "tool_result",
269	          tool_use_id: use.id,
270	          content: ok ? `Wrote ${path}.` : `Could not write ${path}.`,
271	          is_error: !ok,
272	        });
273	      } else if (use.name === "delete_file") {
274	        const ok = await opts.onDelete(path);
275	        if (ok) yield { type: "file", path, action: "delete" };
276	        results.push({
277	          type: "tool_result",
278	          tool_use_id: use.id,
279	          content: ok ? `Deleted ${path}.` : `${path} did not exist.`,
280	          is_error: false,
281	        });
282	      } else {
283	        results.push({
284	          type: "tool_result",
285	          tool_use_id: use.id,
286	          content: `Unknown tool ${use.name}.`,
287	          is_error: true,
288	        });
289	      }
290	    }
291	
292	    messages.push({ role: "user", content: results });
293	  }
294	
295	  yield { type: "usage", model, ...totals };
296	}
