1	import { query, type ModelUsage } from "@anthropic-ai/claude-agent-sdk";
2	import { mkdtemp, mkdir, writeFile, readFile, rm } from "node:fs/promises";
3	import { existsSync } from "node:fs";
4	import { tmpdir } from "node:os";
5	import path from "node:path";
6	import type { AgentEvent, FileMap } from "./agent";
7	
8	// Alternative generation engine, selected with KODELY_ENGINE=sdk.
9	//
10	// Instead of calling the metered Anthropic API with ANTHROPIC_API_KEY, this
11	// drives the Claude Agent SDK, which authenticates with the subscription that
12	// `claude setup-token` logged in on THIS MACHINE. Nothing is metered, so
13	// nothing is billed per build — the point of running it during the testing
14	// period.
15	//
16	// Two things to keep in view while this is switched on:
17	//
18	// 1. COSTS RECORDED HERE ARE IMPUTED, NOT BILLED. The token counts are real —
19	//    taken from the SDK's own modelUsage — but they are priced against the API
20	//    rate card to answer "what would this build have cost on metered billing?".
21	//    No money moves. That keeps the credit meter, the ledger and the margin
22	//    dashboard behaving exactly as they will on metered billing (so they can be
23	//    tested now), but /admin figures are a model, not a statement. See
24	//    meterUsage() below.
25	//
26	// 2. A Claude subscription is licensed for individual use. Running a private
27	//    testing period on it is one thing; serving real customers' generations
28	//    from it is another. Switch KODELY_ENGINE back to `api` before opening up.
29	//
30	// There is deliberately NO fallback to the API engine on failure: if the SDK
31	// is not authenticated this throws, rather than quietly spending money on the
32	// metered key that the operator asked not to use.
33	
34	// The shared SYSTEM prompt is written for the API engine, which exposes
35	// custom `write_file` / `delete_file` tools. The SDK exposes its own
36	// Read/Write/Edit/Bash/Glob/Grep instead, so that sentence is not just
37	// useless here — it actively breaks generation: the agent announces it is
38	// building, reaches for a tool that does not exist, and the run ends having
39	// written nothing. (That is exactly what happened the first time this engine
40	// ran in prod.)
41	const API_TOOL_CONTRACT =
42	  "Use the write_file and delete_file tools. Always pass the complete final file — there is no patch tool.";
43	
44	const SDK_TOOL_CONTRACT = [
45	  "You are editing a real checkout on disk in the working directory.",
46	  "- Use Write to create or replace a file, passing the complete final contents.",
47	  "- Use Edit for a targeted change to an existing file.",
48	  "- Use Read, Glob and Grep to inspect what is already there before changing it.",
49	  "- Delete a file with Bash (`rm`).",
50	  "There is no write_file or delete_file tool — those belong to a different engine.",
51	].join("\n");
52	
53	/**
54	 * Adapt the shared prompt to the SDK's toolset.
55	 *
56	 * Throws if the expected sentence is missing rather than silently sending a
57	 * prompt that names tools the agent does not have — a silent mismatch here is
58	 * invisible until a generation quietly produces zero files.
59	 */
60	export function adaptPromptForSdk(system: string): string {
61	  if (!system.includes(API_TOOL_CONTRACT)) {
62	    throw new Error(
63	      "agent-sdk: the API tool-contract sentence was not found in SYSTEM. " +
64	        "It was probably reworded in lib/agent.ts — update API_TOOL_CONTRACT to match, " +
65	        "or the SDK engine will instruct the agent to call tools it does not have.",
66	    );
67	  }
68	  return system.replace(API_TOOL_CONTRACT, SDK_TOOL_CONTRACT);
69	}
70	
71	// Hide the metered key from the SDK and everything it spawns.
72	//
73	// This runs at module load, and this module is only imported when
74	// KODELY_ENGINE=sdk (see lib/agent.ts), so nothing in this process wants the
75	// API key anyway. Doing it once here — rather than passing a constructed
76	// `env` to query() — matters: an explicit env REPLACES the child's
77	// environment, and under Next.js `process.env` is a proxy that does not
78	// enumerate the full OS environment. Rebuilding it from Object.entries()
79	// therefore dropped USERPROFILE/APPDATA, and the spawned Claude Code could no
80	// longer find ~/.claude/.credentials.json — it failed with "Not logged in"
81	// even on a machine that was logged in. Deleting one key and letting the
82	// child inherit normally avoids that entirely.
83	if (process.env.ANTHROPIC_API_KEY) delete process.env.ANTHROPIC_API_KEY;
84	
85	function assertSdkCredentials(): void {
86	  // Two valid ways to authenticate, and a dev machine usually uses the second:
87	  //   1. CLAUDE_CODE_OAUTH_TOKEN — headless servers (the VM).
88	  //   2. ~/.claude/.credentials.json — written by an interactive
89	  //      `claude setup-token` login, which is what a workstation already has.
90	  // Requiring (1) unconditionally broke local development, where (2) is
91	  // present and perfectly sufficient.
92	  const home = process.env.HOME ?? process.env.USERPROFILE;
93	  const hasCredentialsFile =
94	    !!home && existsSync(path.join(home, ".claude", ".credentials.json"));
95	
96	  if (!process.env.CLAUDE_CODE_OAUTH_TOKEN && !hasCredentialsFile) {
97	    throw new Error(
98	      "KODELY_ENGINE=sdk but no subscription credentials were found. " +
99	        "Either run `claude setup-token` as this user, or set " +
100	        "CLAUDE_CODE_OAUTH_TOKEN in the environment.",
101	    );
102	  }
103	}
104	
105	/**
106	 * Map a raw model id from the SDK onto a key in MODEL_RATES.
107	 *
108	 * The SDK reports concrete ids ("claude-sonnet-5-20250929"), while the rate
109	 * card is keyed by family. Anything unrecognised is returned unchanged so
110	 * costMicros() falls through to its deliberately conservative `default` rate
111	 * — an unknown model should over-estimate, never under-bill.
112	 */
113	function toRateKey(model: string): string {
114	  const m = model.toLowerCase();
115	  if (m.includes("opus")) return "claude-opus-5";
116	  if (m.includes("sonnet")) return "claude-sonnet-5";
117	  if (m.includes("haiku")) return "claude-haiku-4-5";
118	  return model;
119	}
120	
121	/**
122	 * Turn an SDK result into the usage event the charging path expects.
123	 *
124	 * IMPORTANT — what this cost means. On the subscription there is no metered
125	 * per-build charge, so this is an IMPUTED cost: the real tokens this build
126	 * consumed, priced at the API rate card. It is what the build WOULD have cost
127	 * on metered billing, not money that left an account.
128	 *
129	 * That is deliberately more useful than reporting zeros. Zeroed usage made
130	 * every SDK build cost exactly 1 credit (the floor) and flatlined the
131	 * cost/margin dashboard — which is the instrument for the board's "riskiest
132	 * assumption #1", whether infra can beat credit economics. With real token
133	 * counts the credit meter, the ledger and the margin view all behave exactly
134	 * as they will on metered billing, which is what makes them testable now.
135	 *
136	 * `modelUsage` is the field the SDK documents as correct for token accounting:
137	 * it spans the main loop plus subagents and internal calls, where `usage`
138	 * covers only the main loop. It is cumulative per query() call, so it is read
139	 * once from the final result rather than summed across results.
140	 */
141	function meterUsage(message: { modelUsage?: Record<string, ModelUsage> }): {
142	  model: string;
143	  inputTokens: number;
144	  outputTokens: number;
145	  cacheReadTokens: number;
146	  cacheWriteTokens: number;
147	} {
148	  const usage = message.modelUsage ?? {};
149	  const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
150	
151	  // The charging path takes ONE model string plus summed tokens, so attribute
152	  // the build to whichever model produced the most output tokens — output
153	  // dominates cost on every rate in the card. In practice Claude Code runs one
154	  // model for the main loop, so this is usually exact; when a cheap auxiliary
155	  // model also ran, its tokens are still counted, just priced at the main
156	  // model's rate. That errs toward over-billing, never under.
157	  let dominant = "";
158	  let mostOutput = -1;
159	
160	  for (const [model, u] of Object.entries(usage)) {
161	    totals.inputTokens += u.inputTokens ?? 0;
162	    totals.outputTokens += u.outputTokens ?? 0;
163	    totals.cacheReadTokens += u.cacheReadInputTokens ?? 0;
164	    totals.cacheWriteTokens += u.cacheCreationInputTokens ?? 0;
165	    if ((u.outputTokens ?? 0) > mostOutput) {
166	      mostOutput = u.outputTokens ?? 0;
167	      dominant = u.canonicalModel ?? model;
168	    }
169	  }
170	
171	  return {
172	    // No usage at all (a crashed or startup-error result) keeps the old
173	    // self-explaining tag, so a 1-credit build is visibly "no telemetry"
174	    // rather than looking like a genuinely free one.
175	    model: dominant ? toRateKey(dominant) : "claude-agent-sdk-subscription",
176	    ...totals,
177	  };
178	}
179	
180	/** Reject path traversal and absolute paths before anything touches the DB. */
181	function safeRelPath(raw: string): string | null {
182	  const p = raw.trim().replace(/^\.?\//, "");
183	  if (!p || p.length > 200) return null;
184	  if (p.includes("..") || p.startsWith("/") || p.includes("\\")) return null;
185	  if (!/^[A-Za-z0-9._/-]+$/.test(p)) return null;
186	  return p;
187	}
188	
189	async function writeFileMap(dir: string, files: FileMap) {
190	  for (const [rel, content] of Object.entries(files)) {
191	    const full = path.join(dir, rel);
192	    await mkdir(path.dirname(full), { recursive: true });
193	    await writeFile(full, content, "utf8");
194	  }
195	}
196	
197	async function readFileTree(dir: string, prefix = ""): Promise<FileMap> {
198	  const { readdir } = await import("node:fs/promises");
199	  const out: FileMap = {};
200	  const entries = await readdir(dir, { withFileTypes: true });
201	  for (const e of entries) {
202	    if (e.name === "node_modules" || e.name === ".git" || e.name.startsWith(".")) continue;
203	    const rel = prefix ? `${prefix}/${e.name}` : e.name;
204	    const full = path.join(dir, e.name);
205	    if (e.isDirectory()) Object.assign(out, await readFileTree(full, rel));
206	    else out[rel] = await readFile(full, "utf8");
207	  }
208	  return out;
209	}
210	
211	type SdkOptions = {
212	  history: { role: "user" | "assistant"; content: string }[];
213	  request: string;
214	  files: FileMap;
215	  kind: "create" | "edit";
216	  image?: { mediaType: string; data: string };
217	  onWrite: (path: string, content: string) => Promise<boolean>;
218	  onDelete: (path: string) => Promise<boolean>;
219	  signal?: AbortSignal;
220	};
221	
222	export async function* runAgentSdk(
223	  opts: SdkOptions,
224	  systemPrompt: string,
225	): AsyncGenerator<AgentEvent> {
226	  // The SDK edits a real directory rather than calling tools over the wire,
227	  // so the project is materialised to a temp dir and diffed afterwards.
228	  assertSdkCredentials();
229	  const workDir = await mkdtemp(path.join(tmpdir(), "kodely-sdk-"));
230	
231	  try {
232	    await writeFileMap(workDir, opts.files);
233	
234	    let imageNote = "";
235	    if (opts.image) {
236	      const ext = opts.image.mediaType.split("/")[1] ?? "png";
237	      await writeFile(path.join(workDir, `.reference.${ext}`), Buffer.from(opts.image.data, "base64"));
238	      imageNote = `\n\nA reference image was attached to this request — Read the file .reference.${ext} in this directory to see it, then use it as visual/style guidance.`;
239	    }
240	
241	    const historyText = opts.history.length
242	      ? `## Prior conversation on this project\n${opts.history
243	          .map((h) => `${h.role === "user" ? "User" : "You"}: ${h.content}`)
244	          .join("\n\n")}\n\n`
245	      : "";
246	
247	    yield {
248	      type: "status",
249	      text: opts.kind === "create" ? "Building your site…" : "Applying your changes…",
250	    };
251	
252	    for await (const message of query({
253	      prompt: `${historyText}## Current request\n${opts.request}${imageNote}`,
254	      options: {
255	        cwd: workDir,
256	        systemPrompt: adaptPromptForSdk(systemPrompt),
257	        allowedTools: ["Read", "Write", "Edit", "Bash", "Glob", "Grep"],
258	        permissionMode: "acceptEdits",
259	      },
260	    })) {
261	      if (opts.signal?.aborted) break;
262	
263	      if (message.type === "assistant" && message.message?.content) {
264	        for (const block of message.message.content) {
265	          if ("text" in block && block.text) yield { type: "text", text: block.text };
266	        }
267	      } else if (message.type === "result") {
268	        yield { type: "usage", ...meterUsage(message) };
269	      }
270	    }
271	
272	    if (opts.signal?.aborted) return;
273	
274	    // Diff the directory back into write/delete events so the caller persists
275	    // exactly what the API engine would have produced.
276	    const after = await readFileTree(workDir);
277	
278	    for (const [p, content] of Object.entries(after)) {
279	      if (p.startsWith(".reference.")) continue;
280	      const rel = safeRelPath(p);
281	      if (!rel) continue;
282	      if (opts.files[p] === content) continue; // unchanged
283	      if (await opts.onWrite(rel, content)) yield { type: "file", path: rel, action: "write" };
284	    }
285	    for (const p of Object.keys(opts.files)) {
286	      if (p in after) continue;
287	      const rel = safeRelPath(p);
288	      if (!rel) continue;
289	      if (await opts.onDelete(rel)) yield { type: "file", path: rel, action: "delete" };
290	    }
291	  } finally {
292	    // On Windows a just-exited child can hold the dir briefly (EBUSY); retry,
293	    // and never let cleanup failure mask a successful generation.
294	    try {
295	      await rm(workDir, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
296	    } catch {}
297	  }
298	}
