11	function sse(event: unknown) {
12	  return `data: ${JSON.stringify(event)}\n\n`;
13	}
14	
15	// A build that fails to compile even after one repair attempt gives up — this
16	// bounds the worst case to ~2x the cost of a normal generation, not unbounded.
17	const MAX_BUILD_ATTEMPTS = 2;
18	
19	export async function POST(req: Request) {
20	  const user = await getCurrentUser();
21	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
22	
23	  const body = (await req.json().catch(() => null)) as {
24	    projectId?: string;
25	    prompt?: string;
26	    image?: string;
27	  } | null;
28	  const prompt = body?.prompt?.trim();
29	  if (!body?.projectId || !prompt) {
30	    return Response.json({ error: "Missing project or prompt." }, { status: 400 });
31	  }
32	
33	  // Only a data: URL (what the client-side downscale in PromptHero produces)
34	  // is accepted — anything else is silently dropped rather than passed on.
35	  const imageMatch = body.image?.match(/^data:(image\/(?:png|jpeg|webp));base64,(.+)$/);
36	  const image = imageMatch ? { mediaType: imageMatch[1], data: imageMatch[2] } : undefined;
37	
38	  const project = await db.project.findFirst({
39	    where: { id: body.projectId, userId: user.id },
40	    include: { messages: { orderBy: { createdAt: "asc" } } },
41	  });
42	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
43	
44	  const balance = await getBalance(user.id);
45	  if (balance <= 0) {
46	    return Response.json(
47	      { error: "You're out of credits. Top up to keep building." },
48	      { status: 402 },
49	    );
50	  }
51	
52	  const rateLimit = await checkGenerateRateLimit(user.id);
53	  if (!rateLimit.allowed) {
54	    return Response.json(
55	      { error: "You're generating too fast — take a short break and try again shortly." },
56	      { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
57	    );
58	  }
59	
60	  // The foundation means source files are never empty — "first build" is
61	  // instead "first real customization request" for this project.
62	  const kind = project.messages.length === 0 ? "create" : "edit";
63	
64	  const build = await db.build.create({
65	    data: { projectId: project.id, status: "RUNNING", model: "", prompt },
66	  });
67	
68	  await db.message.create({
69	    data: { projectId: project.id, role: "user", content: prompt },
70	  });
71	
72	  // Aborted when the client disconnects (tab closed, network drop) — cancels
73	  // the in-flight Anthropic request instead of burning tokens for nobody.
74	  const abortController = new AbortController();
75	
76	  const encoder = new TextEncoder();
77	  const stream = new ReadableStream({
78	    async start(controller) {
79	      // A client disconnect races with our own sends: enqueue on a closed
80	      // controller throws "Controller is already closed", which used to be
81	      // caught as a generic failure and wrongly mark an otherwise-fine build
82	      // FAILED. There's nothing to do about a gone client — swallow it.
83	      const send = (event: unknown) => {
84	        try {
85	          controller.enqueue(encoder.encode(sse(event)));
86	        } catch {
87	          // client is gone
88	        }
89	      };
90	
91	      let filesWritten = 0;
92	      let succeeded = false;
93	      const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
94	      let model = "";
95	      let lastReply = "";
96	
97	      const readSourceFiles = async (): Promise<FileMap> => {
98	        const rows = await db.projectFile.findMany({
99	          where: { projectId: project.id, published: false, kind: "source" },
100	        });
101	        return Object.fromEntries(rows.map((f) => [f.path, f.content]));
102	      };
103	
104	      try {
105	        let request = prompt;
106	        let buildOutput: FileMap | null = null;
107	        let lastBuildError = "";
108	
109	        for (let attempt = 1; attempt <= MAX_BUILD_ATTEMPTS; attempt++) {
110	          if (abortController.signal.aborted) break;
111	
112	          const generator = runAgent({
113	            history: project.messages.map((m) => ({
114	              role: m.role === "assistant" ? ("assistant" as const) : ("user" as const),
115	              content: m.content,
116	            })),
117	            request,
118	            files: await readSourceFiles(),
119	            kind,
120	            // Only attached on the very first turn of a project — a repair
121	            // retry re-sends the same `request` text but should not attach
122	            // the image again mid-loop.
123	            image: attempt === 1 ? image : undefined,
124	            signal: abortController.signal,
125	            onWrite: async (path, content) => {
126	              if (!normalizePath(path)) return false;
127	              await db.projectFile.upsert({
128	                where: {
129	                  projectId_path_published_kind: {
130	                    projectId: project.id,
131	                    path,
132	                    published: false,
133	                    kind: "source",
134	                  },
135	                },
136	                create: { projectId: project.id, path, content, published: false, kind: "source" },
137	                update: { content },
138	              });
139	              filesWritten++;
140	              return true;
141	            },
142	            onDelete: async (path) => {
143	              const { count } = await db.projectFile.deleteMany({
144	                where: { projectId: project.id, path, published: false, kind: "source" },
145	              });
146	              return count > 0;
147	            },
148	          });
149	
150	          for await (const event of generator) {
151	            if (event.type === "text") {
152	              lastReply += event.text;
153	              send(event);
154	            } else if (event.type === "file") {
155	              send(event);
156	            } else if (event.type === "usage") {
157	              model = event.model;
158	              totals.inputTokens += event.inputTokens;
159	              totals.outputTokens += event.outputTokens;
160	              totals.cacheReadTokens += event.cacheReadTokens;
161	              totals.cacheWriteTokens += event.cacheWriteTokens;
162	            }
163	          }
164	
165	          if (abortController.signal.aborted) break;
166	
167	          try {
168	            buildOutput = await buildSite(await readSourceFiles());
169	            break; // compiled cleanly — done
170	          } catch (err) {
171	            lastBuildError = err instanceof BuildError ? err.message : String(err);
172	            if (attempt >= MAX_BUILD_ATTEMPTS) throw new Error(lastBuildError);
173	            send({ type: "status", text: "Build didn't compile — fixing it…" });
174	            request = `The last change failed to build. Fix it and keep the rest of the change. Build error:\n${lastBuildError}`;
175	          }
176	        }
177	
178	        if (abortController.signal.aborted || !buildOutput) {
179	          // Loop ended without a successful build and without throwing —
180	          // only reachable via the abort path (see the `break` above).
181	        } else {
182	          succeeded = true;
183	
184	          // Replace the compiled tree with the new build output.
185	          await db.$transaction([
186	            db.projectFile.deleteMany({ where: { projectId: project.id, published: false, kind: "build" } }),
187	            ...(Object.keys(buildOutput).length > 0
188	              ? [
189	                  db.projectFile.createMany({
190	                    data: Object.entries(buildOutput).map(([path, content]) => ({
191	                      projectId: project.id,
192	                      path,
193	                      content,
194	                      published: false,
195	                      kind: "build",
196	                    })),
197	                  }),
198	                ]
199	              : []),
200	          ]);
201	
202	          const micros = costMicros(model, totals);
203	          const credits = creditsFor(micros);
204	          const remaining = await chargeForBuild(user.id, build.id, credits);
205	
206	          const sourceFiles = await readSourceFiles();
207	          const filesSnapshot = { source: sourceFiles, build: buildOutput };
208	
209	          await db.build.update({
210	            where: { id: build.id },
211	            data: {
212	              status: "SUCCEEDED",
213	              model,
214	              endedAt: new Date(),
215	              inputTokens: totals.inputTokens,
216	              outputTokens: totals.outputTokens,
217	              cacheReadTokens: totals.cacheReadTokens,
218	              cacheWriteTokens: totals.cacheWriteTokens,
219	              filesWritten,
220	              costMicros: micros,
221	              creditsCharged: credits,
222	              filesSnapshot,
223	            },
224	          });
225	
226	          if (lastReply.trim()) {
227	            await db.message.create({
228	              data: { projectId: project.id, role: "assistant", content: lastReply.trim() },
229	            });
230	          }
231	          await db.project.update({ where: { id: project.id }, data: { updatedAt: new Date() } });
232	
233	          send({ type: "done", credits, remaining, filesWritten });
234	        }
235	
236	        if (!succeeded) {
237	          await db.build.update({
238	            where: { id: build.id },
239	            data: {
240	              status: "FAILED",
241	              endedAt: new Date(),
242	              error: abortController.signal.aborted ? "Client disconnected." : "Generation ended without producing output.",
243	              filesWritten,
244	              creditsCharged: 0,
245	            },
246	          });
247	        }
248	      } catch (error) {
249	        // A build that fails is never charged — that is the product promise,
250	        // so the ledger is deliberately untouched on this path.
251	        const message =
252	          error instanceof Error ? error.message : "The build failed unexpectedly.";
253	        console.error("[kodely] build failed", build.id, error);
254	
255	        await db.build.update({
256	          where: { id: build.id },
257	          data: {
258	            status: "FAILED",
259	            endedAt: new Date(),
260	            error: message.slice(0, 1000),
261	            filesWritten,
262	            creditsCharged: 0,
263	          },
264	        });
265	
266	        send({ type: "error", message });
267	      } finally {
268	        try {
269	          controller.close();
270	        } catch {
271	          // already closed by the client disconnect path
272	        }
273	      }
274	    },
275	    cancel() {
276	      // The client disconnected — stop the in-flight Anthropic request
277	      // rather than let it run to completion for a response nobody reads.
278	      abortController.abort();
279	    },
280	  });
281	
282	  return new Response(stream, {
283	    headers: {
284	      "Content-Type": "text/event-stream; charset=utf-8",
285	      "Cache-Control": "no-cache, no-transform",
286	      Connection: "keep-alive",
287	    },
288	  });
289	}
