1	import { CONTACT_TO, isMailConfigured, sendContactEmail } from "@/lib/mail";
2	
3	// This endpoint is UNAUTHENTICATED (a contact form has to be), so it is the
4	// one route on the site any stranger can use to make the server send mail.
5	// That makes it a spam target, hence the honeypot + per-IP throttle below.
6	
7	const MAX_PER_IP_PER_HOUR = 5;
8	
9	// In-memory throttle. Deliberately not the DB-backed lib/rate-limit.ts, which
10	// keys on userId — there is no user here. Resets on deploy and is per-process,
11	// so it is a speed bump rather than a guarantee; that is the right weight for
12	// a contact form. If this ever needs to be real, move it to the DB.
13	const hits = new Map<string, number[]>();
14	
15	function rateLimited(ip: string): boolean {
16	  const now = Date.now();
17	  const cutoff = now - 3_600_000;
18	  const recent = (hits.get(ip) ?? []).filter((t) => t > cutoff);
19	  // Bound the map so a flood of unique IPs can't grow it without limit.
20	  if (hits.size > 5000) hits.clear();
21	  if (recent.length >= MAX_PER_IP_PER_HOUR) {
22	    hits.set(ip, recent);
23	    return true;
24	  }
25	  recent.push(now);
26	  hits.set(ip, recent);
27	  return false;
28	}
29	
30	function clientIp(req: Request): string {
31	  // Behind Cloudflare -> host nginx -> VM nginx, so the socket address is
32	  // always a proxy. Trust the forwarded chain's first entry.
33	  const fwd = req.headers.get("x-forwarded-for");
34	  return fwd?.split(",")[0]?.trim() || req.headers.get("cf-connecting-ip") || "unknown";
35	}
36	
37	export async function POST(req: Request) {
38	  if (!isMailConfigured()) {
39	    return Response.json(
40	      { error: `Email isn't set up yet — reach us directly at ${CONTACT_TO}.` },
41	      { status: 503 },
42	    );
43	  }
44	
45	  let body: { name?: unknown; email?: unknown; message?: unknown; company?: unknown };
46	  try {
47	    body = await req.json();
48	  } catch {
49	    return Response.json({ error: "Invalid request." }, { status: 400 });
50	  }
51	
52	  // Honeypot: a field hidden from humans via CSS. Bots fill every input they
53	  // find, so a non-empty value means automation. Return 200 so the bot thinks
54	  // it succeeded and doesn't retry with a different shape.
55	  if (typeof body.company === "string" && body.company.trim() !== "") {
56	    return Response.json({ ok: true });
57	  }
58	
59	  const name = typeof body.name === "string" ? body.name.trim() : "";
60	  const email = typeof body.email === "string" ? body.email.trim() : "";
61	  const message = typeof body.message === "string" ? body.message.trim() : "";
62	
63	  if (!name || !email || !message) {
64	    return Response.json({ error: "Please fill in every field." }, { status: 400 });
65	  }
66	  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
67	    return Response.json({ error: "That email address doesn't look right." }, { status: 400 });
68	  }
69	  if (message.length > 5000) {
70	    return Response.json({ error: "That message is too long (5000 characters max)." }, { status: 400 });
71	  }
72	
73	  if (rateLimited(clientIp(req))) {
74	    return Response.json(
75	      { error: "Too many messages from this address. Try again later." },
76	      { status: 429 },
77	    );
78	  }
79	
80	  try {
81	    await sendContactEmail({ name, email, message });
82	  } catch (err) {
83	    // Never surface SMTP internals (host, credentials, provider errors) to an
84	    // unauthenticated caller; log for the operator instead.
85	    console.error("[contact] send failed:", err);
86	    return Response.json(
87	      { error: `Couldn't send that. Email us directly at ${CONTACT_TO}.` },
88	      { status: 502 },
89	    );
90	  }
91	
92	  return Response.json({ ok: true });
93	}
