input.new_string:
onKeyDown={(e) => {
  // Enter sends a one-liner, but while a spec is on screen this box
  // is a multi-line editor — there, Enter has to make a newline or
  // the first paragraph break the user types starts a build of a
  // half-edited spec. The send button still works either way.
  if (e.key === "Enter" && !e.shiftKey && enhancedFrom === null) {
    e.preventDefault();
    submit();
  }
}}

onKeyDown={(e) => {
  // Enter sends a one-liner, but while a spec is on screen this
  // box is a multi-line editor — there, Enter has to make a
  // newline or the first paragraph break the user types starts a
  // build of a half-edited spec. The Build button still works.
  if (e.key === "Enter" && !e.shiftKey && enhancedFrom === null) {
    e.preventDefault();
    send();
  }
}}
